std::string now_iso8601() {
  return format_iso8601_utc(now());
}

// The counters of lookup_counters().
std::atomic<std::uint64_t> g_hits{0};    // NOLINT(cppcoreguidelines-avoid-non-const-global-variables)
std::atomic<std::uint64_t> g_misses{0};  // NOLINT(cppcoreguidelines-avoid-non-const-global-variables)

template <class T>
std::optional<T> counted(std::optional<T> result) noexcept {
  (result ? g_hits : g_misses).fetch_add(1, std::memory_order_relaxed);
  return result;
}

// The clock override of set_now_for_testing().
std::mutex& clock_mutex() {
  static std::mutex mu;
  return mu;
}
std::optional<std::chrono::system_clock::time_point>& clock_slot() {
  static std::optional<std::chrono::system_clock::time_point> slot;
  return slot;
}

// `FinishSizePrefixed` framing (§6.1.1) of a buffer that `Finish` produced with an identifier:
// [size:4][root uoffset:4][ident:4][pad:4][body]. The pad is what FinishSizePrefixed inserts for minalign 8
// (every record with an int64: pts, poc, ...), so the body keeps its alignment modulo 8, the Verifier accepts
// the stored buffer and the mmap-ed index.fb is safe for zero-copy readers. The root uoffset is relative to
// its own position and moves by the pad; a minalign-4 body tolerates the pad, so one layout serves every record.
constexpr std::size_t kHeaderBytes = 2 * kSizePrefix;  // root uoffset + identifier
constexpr std::size_t kPadBytes = kSizePrefix;

std::vector<std::uint8_t> add_size_prefix(std::span<const std::uint8_t> buf) {
  if (buf.size() < kHeaderBytes) {
    throw CacheError(OVT_E_INVALID_ARG, "cache: FlatBuffer shorter than its header");
  }
  if (buf.size() > std::numeric_limits<flatbuffers::uoffset_t>::max() - kSizePrefix - kPadBytes) {
    throw CacheError(OVT_E_INVALID_ARG, "cache: FlatBuffer too large for a size prefix");
  }
  std::vector<std::uint8_t> out(kSizePrefix + kHeaderBytes + kPadBytes + (buf.size() - kHeaderBytes));
  flatbuffers::WriteScalar(out.data(), static_cast<flatbuffers::uoffset_t>(out.size() - kSizePrefix));
  const auto root = flatbuffers::ReadScalar<flatbuffers::uoffset_t>(buf.data());
  flatbuffers::WriteScalar(std::span(out).subspan(kSizePrefix).data(),
                           static_cast<flatbuffers::uoffset_t>(root + kPadBytes));
  std::ranges::copy(buf.subspan(kSizePrefix, kSizePrefix), std::span(out).subspan(2 * kSizePrefix).begin());
  std::ranges::copy(buf.subspan(kHeaderBytes), std::span(out).subspan(kSizePrefix + kHeaderBytes + kPadBytes).begin());
  return out;
}

// The inverse of add_size_prefix for a buffer that verify_size_prefixed accepted.
std::vector<std::uint8_t> strip_size_prefix(std::span<const std::uint8_t> prefixed) {
  const std::span<const std::uint8_t> framed = prefixed.subspan(kSizePrefix);
  if (framed.size() < kHeaderBytes + kPadBytes) {
    throw CacheError(OVT_E_CORRUPT, "cache: size-prefixed record shorter than its header");
  }
  std::vector<std::uint8_t> out(framed.size() - kPadBytes);
  const auto root = flatbuffers::ReadScalar<flatbuffers::uoffset_t>(framed.data());
  if (root < kHeaderBytes + kPadBytes) {
    throw CacheError(OVT_E_CORRUPT, "cache: size-prefixed record has no pad after its header");
  }
  flatbuffers::WriteScalar(out.data(), static_cast<flatbuffers::uoffset_t>(root - kPadBytes));
  std::ranges::copy(framed.subspan(kSizePrefix, kSizePrefix), std::span(out).subspan(kSizePrefix).begin());
  std::ranges::copy(framed.subspan(kHeaderBytes + kPadBytes), std::span(out).subspan(kHeaderBytes).begin());
  return out;
}

std::string frame_file_name(std::uint32_t decode_index) {
  std::array<char, 24> buf{};
  const int n = std::snprintf(buf.data(), buf.size(), "%08u", decode_index);
  return {buf.data(), static_cast<std::size_t>(n)};
}

bool valid_report_kind(std::string_view kind) noexcept {
  if (kind.empty() || kind.size() > 32) {
    return false;
  }
  return std::ranges::all_of(kind, [](const char c) {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' || c == '-';
  });
}

std::uint64_t file_size_or_zero(const fs::path& path) noexcept {
  std::error_code ec;
  const auto size = fs::file_size(path, ec);
  return ec ? 0 : size;
}

void ensure_directory(const fs::path& dir) {
  std::error_code ec;
  fs::create_directories(dir, ec);
  if (ec || !fs::is_directory(dir)) {
    throw CacheError(OVT_E_IO, "cache: cannot create directory '" + dir.string() + "': " + ec.message());
  }
}

Meta fresh_meta(const std::string& hex_hash) {
  Meta m;
  m.source_hash = hex_hash;
  m.created = now_iso8601();
  m.last_used = m.created;
  m.ovt_version = OVT_VERSION_FULL;
  m.ovt_model = SchemaRev{model::kModelSchemaMajor, std::string(model::kModelSchemaSha256)};
  m.ovt_container = SchemaRev{model::kContainerSchemaMajor, std::string(model::kContainerSchemaSha256)};
  m.ovt_metrics = SchemaRev{model::kMetricsSchemaMajor, std::string(model::kMetricsSchemaSha256)};
  m.codec = "Unknown";
  m.frame_count = 0;
  m.index_complete = false;
  m.planes_cached = false;
  return m;
}

// The process default root of set_default_root().
std::mutex& default_root_mutex() {
  static std::mutex mu;
  return mu;
}
std::optional<fs::path>& default_root_slot() {
  static std::optional<fs::path> slot;
  return slot;
}

std::string env_or_empty(const char* name) {
  const char* v = std::getenv(name);  // NOLINT(concurrency-mt-unsafe): read-only lookup
  return v != nullptr ? std::string(v) : std::string();
}

// The PlaneRef of @p stage / @p plane in @p fa, or nullptr.
const fb::PlaneRef* find_plane_ref(const fb::FrameAnalysis& fa, fb::PlaneStage stage, std::uint8_t plane) {
  if (fa.planes() != nullptr) {
    for (const fb::PlaneRef* candidate : *fa.planes()) {
      if (candidate->stage() == stage && candidate->plane() == plane) {
        return candidate;
      }
    }
  }
  return nullptr;
}

// A plane read back with the geometry of its PlaneRef (§6.7.1); @p bytes holds height * width * sample_bytes.
PlaneData plane_data(const fb::PlaneRef& ref, fb::PlaneStage stage, std::uint8_t plane,
                     std::vector<std::uint8_t> bytes) {
  PlaneData out;
  out.view.width = ref.width();
  out.view.height = ref.height();
  out.view.sample_bytes = ref.sample_bytes();
  out.view.bit_depth = ref.bit_depth();
  out.view.plane = plane;
  out.view.stage = static_cast<std::uint8_t>(stage);
  switch (ref.sample_bytes()) {
    case 1:
      out.view.format = model::SampleFormat::U8;
      break;
    case 2:
      out.view.format = ref.is_signed() ? model::SampleFormat::S16LE : model::SampleFormat::U16LE;
      break;
    case 4:
      out.view.format = model::SampleFormat::S32LE;
      break;
    default:
      throw CacheError(OVT_E_CORRUPT, "cache: PlaneRef.sample_bytes outside 1, 2, 4");
  }
  out.bytes = std::move(bytes);
  out.view.stride_bytes = ref.width() * ref.sample_bytes();
  out.view.data = out.bytes.data();
  return out;
}

